/**
 * ForgotPasswordForm.tsx – auto‑generated placeholder
 */

"use client";
import Image from 'next/image';
import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { forgotPassword, resetPassword } from '@/features/auth/slices/authSlice';
import { AppDispatch } from '@/features/auth/store';

const PASSWORD_REQUIREMENTS = [
  { label: 'At lease 8 characters', test: (v: string) => v.length >= 8 },
  { label: 'At least one number or symbol', test: (v: string) => /[\d!@#$%^&*(),.?":{}|<>_~`[\]\\;'\/+= -]/.test(v) },
  { label: 'Both uppercase and lowercase letters', test: (v: string) => /[a-z]/.test(v) && /[A-Z]/.test(v) },
];

const ForgetPassword = () => {
  const dispatch = useDispatch<AppDispatch>();
  const [step, setStep] = useState<'email' | 'reset' | 'success'>('email');
  const [email, setEmail] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('user_email') || '';
    }
    return '';
  });
  const [emailError, setEmailError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [resetError, setResetError] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  // Password requirements
  const hasMinChars = PASSWORD_REQUIREMENTS[0].test(password);
  const hasNumberOrSymbol = PASSWORD_REQUIREMENTS[1].test(password);
  const hasMixedCase = PASSWORD_REQUIREMENTS[2].test(password);

  // Step 1: Submit email
  const handleEmailSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setEmailError('');
    if (!email.trim()) {
      setEmailError('Email is required');
      return;
    }
    if (!/\S+@\S+\.\S+/.test(email)) {
      setEmailError('Email is invalid');
      return;
    }
    setIsLoading(true);
    try {
      await dispatch(forgotPassword({ email })).unwrap();
      setStep('reset');
      if (typeof window !== 'undefined') {
        localStorage.setItem('user_email', email);
      }
    } catch (err: any) {
      setEmailError(err || 'Failed to send reset email');
    } finally {
      setIsLoading(false);
    }
  };

  // Step 2: Reset password
  const handleResetSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setResetError('');
    if (!password) {
      setResetError('Password is required');
      return;
    }
    if (!hasMinChars || !hasNumberOrSymbol || !hasMixedCase) {
      setResetError("Password doesn't meet requirements");
      return;
    }
    if (password !== confirmPassword) {
      setResetError('Passwords do not match');
      return;
    }
    setIsLoading(true);
    try {
      await dispatch(resetPassword({ email, password, confirm_password: confirmPassword })).unwrap();
      setStep('success');
    } catch (err: any) {
      setResetError(err || 'Failed to reset password');
    } finally {
      setIsLoading(false);
    }
  };

  // Step 3: Success modal
  const SuccessModal = () => (
    <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-40">
      <div className="bg-[#1D1D23] rounded-2xl p-8 max-w-sm w-full text-center relative">
        <div className="flex items-center justify-center mb-4">
          <div className="bg-[#1D8751] rounded-full w-14 h-14 flex items-center justify-center">
            <svg width="32" height="32" fill="none" viewBox="0 0 24 24"><circle cx="12" cy="12" r="12" fill="#1D8751"/><path d="M7 13l3 3 7-7" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </div>
        </div>
        <h2 className="text-white text-xl font-semibold mb-2">Password changed successfully</h2>
        <button
          className="w-full bg-[#1D8751] text-white py-2 px-4 rounded-full hover:bg-[#0E5531] transition-colors duration-300 mt-4"
          onClick={() => window.location.href = '/auth/login'}
        >
          Log In
        </button>
      </div>
    </div>
  );

  return (
    <div className="flex min-h-screen bg-[#18181D] flex-col md:flex-row items-start justify-center relative overflow-hidden px-6 py-8 md:pt-24">
      {/* Left Side - Mobile App Preview */}
      <div className="w-full md:w-1/2 flex justify-center mb-8 md:mb-0 relative z-10">
         {/* Background Glow Effect */}
         <div className="w-[438px] h-[403px] bg-[#1D8751] blur-[60px]  absolute left-16 2xl:left-54 opacity-60"></div>
        <div className="relative">
          <Image
            src="https://res.cloudinary.com/dam1sxczj/image/upload/v1747220053/iphone_vn7ejc.png"
            alt="OMAYA Exchange Mobile App"
            width={350}
            height={650}
            className="mx-auto "
            priority
          />
          {/* App store badges */}
        <div className="flex space-x-1 mt-4 justify-center">
        <div className="rounded px-2 flex items-center border border-gray-700 bg-white">
            <Image
              src="https://res.cloudinary.com/dam1sxczj/image/upload/v1746787514/Google_Play-Icon-Logo.wine_dqxxk7.svg" 
              alt="Google Play Store" 
              width={40} 
              height={13} 
              className="mr-2"
            />
            <div>
              <p className="text-[#051015] text-xs">Download on the</p>
              <span className="text-[#051015] text-sm font-bold">Google Play</span>
            </div>
          </div>
          <div className="rounded px-2 flex items-center border border-gray-700 bg-white">
            <Image 
              src="https://res.cloudinary.com/dam1sxczj/image/upload/v1747288173/dark_apple_rwpgwi.png" 
              alt="Apple App Store" 
              width={20} 
              height={20} 
              className="mr-2"
            />
            <div>
              <p className="text-[#051015] text-xs">Download on the</p>
              <span className="text-[#051015] text-sm font-bold">App Store</span>
            </div>
          </div>
        </div>
        </div>
      </div>
      
      {/* Right side - Forgot password flow */}
      <div className="w-1/2 p-8 flex flex-col justify-center">
        <div className="max-w-md mx-auto w-full 2xl:max-w-3/4">
          {step === 'email' && (
            <>
              <h1 className="text-2xl font-semibold text-white mb-2">Forgot Password</h1>
              <p className="text-[#788099] mb-1">
                Enter your email to receive the instruction <br />
                to reset your password
              </p>
              <form className="space-y-4" onSubmit={handleEmailSubmit}>
                <div className="grid grid-cols-1 gap-4">
                  <div>
                    <label htmlFor="email" className="block text-white text-sm mb-2">
                      Email*
                    </label>
                    <div className="relative">
                      <input
                        type="email"
                        id="email"
                        value={email}
                        onChange={e => setEmail(e.target.value)}
                        placeholder="Email Address"
                        className="w-full py-2 px-4 pl-9 bg-[#1D1D23] border border-[#35353E] rounded-full  text-[#788099] placeholder-[#788099] focus:outline-none focus:ring-2 focus:ring-[#1D8751] focus:border-transparent"
                      />
                      <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                          <rect x="2" y="4" width="16" height="12" rx="2" stroke="#1D8751" strokeWidth="1.5" />
                          <path d="M18 6L10 11L2 6" stroke="#1D8751" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                      </div>
                    </div>
                    {emailError && <p className="text-[#F04438] text-sm mt-1">{emailError}</p>}
                  </div>
                </div>
                <button
                  type="submit"
                  className="w-full bg-[#1D8751] text-white py-2 px-4 rounded-full hover:bg-[#0E5531] transition-colors duration-300 mt-4"
                  disabled={isLoading}
                >
                  {isLoading ? 'Sending...' : 'Confirm'}
                </button>
              </form>
            </>
          )}
          {step === 'reset' && (
            <>
              <h1 className="text-2xl font-semibold text-white mb-2">Forgot Password</h1>
              <p className="text-[#788099] mb-1">Create New Password</p>
              <form className="space-y-4" onSubmit={handleResetSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label htmlFor="new-password" className="block text-white text-sm mb-2">New Password*</label>
                    <div className="relative">
                      <input
                        type={showPassword ? 'text' : 'password'}
                        id="new-password"
                        value={password}
                        onChange={e => setPassword(e.target.value)}
                        placeholder="Enter password"
                        className="w-full py-2 px-4 pl-9 bg-[#1D1D23] border border-[#35353E] rounded-full text-[#788099] placeholder-[#788099] focus:outline-none focus:ring-2 focus:ring-[#1D8751] focus:border-transparent"
                      />
                      <button
                        type="button"
                        className="absolute inset-y-0 right-0 pr-3 flex items-center"
                        onClick={() => setShowPassword(!showPassword)}
                        tabIndex={-1}
                      >
                        {showPassword ? (
                          <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M2 10C2 10 5 4 10 4C15 4 18 10 18 10C18 10 15 16 10 16C5 16 2 10 2 10Z" stroke="#788099" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                            <path d="M10 12C11.1046 12 12 11.1046 12 10C12 8.89543 11.1046 8 10 8C8.89543 8 8 8.89543 8 10C8 11.1046 8.89543 12 10 12Z" stroke="#788099" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                          </svg>
                        ) : (
                          <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M4.5 4.5L15.5 15.5" stroke="#788099" strokeWidth="1.5" strokeLinecap="round"/>
                            <path d="M11.843 11.844C11.5128 12.1745 11.1023 12.4138 10.6513 12.5398C10.2003 12.6658 9.72401 12.6745 9.26875 12.565C8.81348 12.4555 8.39456 12.2315 8.05372 11.9155C7.71288 11.5994 7.4619 11.2024 7.325 10.763" stroke="#788099" strokeWidth="1.5" strokeLinecap="round"/>
                            <path d="M8.5 5.016C9.017 4.926 9.549 4.879 10.093 4.879C14.5 4.879 17 10 17 10C17 10 16.307 11.323 15 12.5" stroke="#788099" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                            <path d="M2 10C2 10 4 6 8.5 4.5" stroke="#788099" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                            <path d="M7 7L13 13" stroke="#788099" strokeWidth="1.5" strokeLinecap="round"/>
                          </svg>
                        )}
                      </button>
                    </div>
                  </div>
                  <div>
                    <label htmlFor="confirm-password" className="block text-white text-sm mb-2">Confirm password*</label>
                    <div className="relative">
                      <input
                        type={showConfirmPassword ? 'text' : 'password'}
                        id="confirm-password"
                        value={confirmPassword}
                        onChange={e => setConfirmPassword(e.target.value)}
                        placeholder="Confirm password"
                        className="w-full py-2 px-4 pl-9 bg-[#1D1D23] border border-[#35353E] rounded-full text-[#788099] placeholder-[#788099] focus:outline-none focus:ring-2 focus:ring-[#1D8751] focus:border-transparent"
                      />
                      <button
                        type="button"
                        className="absolute inset-y-0 right-0 pr-3 flex items-center"
                        onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                        tabIndex={-1}
                      >
                        {showConfirmPassword ? (
                          <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M2 10C2 10 5 4 10 4C15 4 18 10 18 10C18 10 15 16 10 16C5 16 2 10 2 10Z" stroke="#788099" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                            <path d="M10 12C11.1046 12 12 11.1046 12 10C12 8.89543 11.1046 8 10 8C8.89543 8 8 8.89543 8 10C8 11.1046 8.89543 12 10 12Z" stroke="#788099" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                          </svg>
                        ) : (
                          <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M4.5 4.5L15.5 15.5" stroke="#788099" strokeWidth="1.5" strokeLinecap="round"/>
                            <path d="M11.843 11.844C11.5128 12.1745 11.1023 12.4138 10.6513 12.5398C10.2003 12.6658 9.72401 12.6745 9.26875 12.565C8.81348 12.4555 8.39456 12.2315 8.05372 11.9155C7.71288 11.5994 7.4619 11.2024 7.325 10.763" stroke="#788099" strokeWidth="1.5" strokeLinecap="round"/>
                            <path d="M8.5 5.016C9.017 4.926 9.549 4.879 10.093 4.879C14.5 4.879 17 10 17 10C17 10 16.307 11.323 15 12.5" stroke="#788099" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                            <path d="M2 10C2 10 4 6 8.5 4.5" stroke="#788099" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                            <path d="M7 7L13 13" stroke="#788099" strokeWidth="1.5" strokeLinecap="round"/>
                          </svg>
                        )}
                      </button>
                    </div>
                  </div>
                </div>
                {/* Password requirements */}
                <div className="flex flex-col space-y-1 ml-1 mt-2">
                  <div className="flex items-center space-x-2">
                    <div className={`h-2 w-2 rounded-full ${hasMinChars ? "bg-[#1D8751]" : "bg-[#F04438]"}`}></div>
                    <span className="text-sm text-white">At lease 8 characters</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <div className={`h-2 w-2 rounded-full ${hasNumberOrSymbol ? "bg-[#1D8751]" : "bg-[#F04438]"}`}></div>
                    <span className="text-sm text-white">At least one number or symbol</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <div className={`h-2 w-2 rounded-full ${hasMixedCase ? "bg-[#1D8751]" : "bg-[#F04438]"}`}></div>
                    <span className="text-sm text-white">Both uppercase and lowercase letters</span>
                  </div>
                </div>
                {resetError && <p className="text-[#F04438] text-sm mt-1">{resetError}</p>}
                <button
                  type="submit"
                  className="w-full bg-[#1D8751] text-white py-2 px-4 rounded-full hover:bg-[#0E5531] transition-colors duration-300 mt-4"
                  disabled={isLoading}
                >
                  {isLoading ? 'Updating...' : 'Update Password'}
                </button>
              </form>
            </>
          )}
          {step === 'success' && <SuccessModal />}
        </div>
      </div>
    </div>
  );
};

export default ForgetPassword;